import json
import unified_planning
from unified_planning.io import PDDLReader
from unified_planning.shortcuts import OneshotPlanner

def solve():
    try:
        with open('problem.json', 'r') as f:
            tasks = json.load(f)
    except FileNotFoundError:
        print("problem.json not found")
        return

    reader = PDDLReader()

    for task in tasks:
        domain_path = task['domain']
        problem_path = task['problem']
        output_path = task['plan_output']

        print(f"Solving {task['id']}...")
        try:
            problem = reader.parse_problem(domain_path, problem_path)
        except Exception as e:
            print(f"Error parsing {task['id']}: {e}")
            continue

        # Try multiple planners if pyperplan fails or is not found
        planner_names = ['pyperplan', 'tamer', 'fast-downward']
        plan = None
        for planner_name in planner_names:
            try:
                with OneshotPlanner(name=planner_name) as planner:
                    result = planner.solve(problem)
                    if result.plan:
                        plan = result.plan
                        print(f"Found plan for {task['id']} using {planner_name}")
                        break
            except Exception as e:
                print(f"Planner {planner_name} failed for {task['id']}: {e}")
                continue

        if plan:
            with open(output_path, 'w') as out:
                for action in plan.actions:
                    # action is an ActionInstance
                    # action.action is the Action object
                    # action.actual_parameters are FNodes
                    params = []
                    for p in action.actual_parameters:
                        if p.is_object_exp():
                            params.append(p.object().name)
                        elif p.is_constant_exp():
                            params.append(str(p.constant_value()))
                        else:
                            params.append(str(p))
                    action_str = f"{action.action.name}({', '.join(params)})"
                    out.write(action_str + '\n')
            print(f"Plan saved to {output_path}")
        else:
            print(f"No plan found for {task['id']}")

if __name__ == "__main__":
    solve()

